-  return amount;
-}
+export interface RevenueInput {
+  subtotalCents: number;
+  taxCents?: number;
+  discountCents?: number;
+}
+
+export function calculateRevenue(input: RevenueInput): number {
+  const subtotal = normalizeMoney(input.subtotalCents);
+  const tax = normalizeMoney(input.taxCents ?? 0);
+  const discount = normalizeMoney(input.discountCents ?? 0);
+
+  const total = subtotal + tax - discount;
+  return total >= 0 ? total : 0;
+}
+
+function normalizeMoney(value: number): number {
+  if (!Number.isInteger(value)) {
+    throw new Error('Money values must be integer cents');
+  }
+
+  if (value < 0) {
+    throw new Error('Money values must be non-negative');
+  }
+
+  return value;
+}
